"use client";
import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { useFlowGroup } from "@/lib/sahajiv-motion/use-flow";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Label, type LabelProps } from "@/components/ui/label";
const FieldContext = React.createContext<{
  id: string;
  invalid: boolean;
} | null>(null);
const fieldVariants = cva(
  "v-field grid gap-[8px] [border:0] bg-transparent [box-shadow:none]",
  {
    variants: { variant: { default: "", invalid: "-invalid" } },
    defaultVariants: { variant: "default" },
  },
);
export type FieldProps = React.ComponentProps<"div"> &
  VariantProps<typeof fieldVariants> & {
    invalid?: boolean;
    controlId?: string;
  };
export function Field({
  className,
  variant,
  invalid = variant === "invalid",
  controlId,
  children,
  ...props
}: FieldProps) {
  const generatedId = React.useId();
  return (
    <FieldContext.Provider value={{ id: controlId ?? generatedId, invalid }}>
      <div
        data-slot="field"
        data-part="root"
        data-state={invalid ? "error" : "rest"}
        className={cn(
          fieldVariants({ variant: invalid ? "invalid" : variant }),
          className,
        )}
        {...props}
      >
        {children}
      </div>
    </FieldContext.Provider>
  );
}
export type FieldLabelProps = LabelProps;
export function FieldLabel(props: FieldLabelProps) {
  const field = React.useContext(FieldContext);
  return (
    <Label
      data-slot="field-label"
      data-part="label"
      htmlFor={field?.id}
      {...props}
    />
  );
}
export type FieldControlProps = React.ComponentProps<typeof Slot>;
export function FieldControl({ children, ...props }: FieldControlProps) {
  const field = React.useContext(FieldContext);
  return (
    <Slot
      data-part="input"
      id={field?.id}
      aria-invalid={field?.invalid || undefined}
      aria-describedby={field ? `${field.id}-message` : undefined}
      {...props}
    >
      {children}
    </Slot>
  );
}
export type FieldDescriptionProps = React.ComponentProps<"p">;
export function FieldDescription({
  className,
  ...props
}: FieldDescriptionProps) {
  const field = React.useContext(FieldContext);
  return (
    <p
      data-slot="field-description"
      data-part="message"
      id={field ? `${field.id}-message` : undefined}
      className={cn(
        "v-help min-h-[1.3em] text-[length:var(--fs-meta)] text-[color:var(--v-text-2)]",
        className,
      )}
      {...props}
    />
  );
}
export type FieldErrorProps = FieldDescriptionProps & {
  errors?: Array<{ message?: string } | undefined>;
};
export function FieldError({ errors, children, ...props }: FieldErrorProps) {
  return (
    <FieldDescription role="alert" {...props}>
      {children ??
        [
          ...new Set(errors?.map((error) => error?.message).filter(Boolean)),
        ].join(" ")}
    </FieldDescription>
  );
}
export type FieldSetProps = React.ComponentProps<"fieldset">;
export function FieldSet({ ref, className, ...props }: FieldSetProps) {
  const flowRef = useFlowGroup<HTMLFieldSetElement>(ref);
  return (
    <fieldset
      ref={flowRef}
      data-flow-fields=""
      data-slot="field-set"
      className={cn("grid min-w-0 gap-[var(--s-5)] [border:0] p-0", className)}
      {...props}
    />
  );
}
export type FieldLegendProps = React.ComponentProps<"legend">;
export function FieldLegend({ className, ...props }: FieldLegendProps) {
  return (
    <legend
      data-slot="field-legend"
      className={cn(
        "v-label text-[length:var(--fs-lead)] font-semibold",
        className,
      )}
      {...props}
    />
  );
}
export type FieldGroupProps = React.ComponentProps<"div"> & { asChild?: boolean };
export function FieldGroup({ ref, asChild, className, ...props }: FieldGroupProps) {
  const flowRef = useFlowGroup<HTMLDivElement>(ref);
  const Comp = asChild ? Slot : "div";
  return (
    <Comp
      ref={flowRef}
      data-flow-fields=""
      data-slot="field-group"
      className={cn(!asChild && "grid gap-[var(--s-5)]", className)}
      {...props}
    />
  );
}
export { fieldVariants };

@layer sahajiv-states {
[data-slot="field"].-invalid .v-help {
  color: var(--v-danger-ink);
}
[data-slot="field"]:has(:disabled) .v-label {
  color: var(--v-disabled-ink);
}
[data-slot="field"].-invalid :is(.v-input, .v-textarea) {
  box-shadow: inset 0 0 0 2px var(--v-danger);
  background: color-mix(in oklab, var(--v-danger) 6%, var(--input));
}
[data-slot="field"].-ok .v-input {
  box-shadow: inset 0 0 0 2px var(--v-olive);
}
[data-slot="field"].-ok .v-help {
  color: var(--v-olive-ink);
}
:root[data-mode="dark"] [data-slot="field"].-invalid .v-input {
  background: color-mix(in oklab, var(--v-danger) 14%, var(--v-canvas));
}
[data-slot="field"]:is(.-error, [data-invalid]) .v-input {
  box-shadow: inset 0 0 0 1.5px var(--v-danger-fill);
  background: var(--v-danger-soft);
}
[data-slot="field"]:is(.-error, [data-invalid]) .v-input:focus-within {
  box-shadow: inset 0 0 0 2px var(--v-danger-fill);
}

[data-slot="field"].-invalid .v-input { border: 1.5px solid var(--v-danger); }

}
